 if x['approval']=='approved':
  if x['field']=='allowed_sessions':a[x['person_id']]=x['value'].split(';')
  if x['field']=='tier':r[x['person_id']]['tier']=x['value']
  if x['field']=='access_required':r[x['person_id']]['access_required']=x['value']
  if x['field']=='active':r[x['person_id']]['active']=x['value']
