 print(s,collections.Counter((p['tier'],p['access_required']) for id,p in r.items() if p['active']=='true' and s in a[id]))
print('access mandatory',sum(p['active']=='true' and p['tier']=='mandatory' and p['access_required']=='true' for p in r.values()))
